import React, { useMemo } from 'react';
import { parse } from 'marked';
import DOMPurify from 'dompurify';
import BriefingReport from './BriefingReport';
import ImageAnalysisReport from './ImageAnalysisReport';
import LabReport from './LabReport';
import InteractionMatrix from './InteractionMatrix';
import ReasoningIndicator from './ReasoningIndicator';
import { isJsonBriefing, isImageAnalysis, isLabReport, isInteractionMatrix } from '../utils';
import { ChatMode } from '../types';

interface MessageContentProps {
    content: string;
    role: 'user' | 'model';
    isLoading: boolean;
    isLast: boolean;
}

const MessageContent: React.FC<MessageContentProps> = ({ content, role, isLoading, isLast }) => {
    // 1. Detect Specialized Report Types
    const isBriefing = role === 'model' && isJsonBriefing(content);
    const isAnalysis = role === 'model' && isImageAnalysis(content);
    const isLab = role === 'model' && isLabReport(content);
    const isInteraction = role === 'model' && isInteractionMatrix(content);

    // 2. Detect Streaming JSON State
    const isStreamingJson = useMemo(() => {
        if (role !== 'model' || !isLoading || !isLast) return false;
        const trimmed = content.trim();
        const hasJsonStart = trimmed.includes('```json') || trimmed.startsWith('{');
        // If it looks like JSON but isn't a complete recognized report yet
        return hasJsonStart && !(isBriefing || isAnalysis || isLab || isInteraction);
    }, [content, role, isLoading, isLast, isBriefing, isAnalysis, isLab, isInteraction]);

    // 3. Detect Placeholder Loading State
    const isPlaceholderLoading = role === 'model' && isLast && isLoading && !content.trim();

    // 4. Memoized Markdown Parsing (Performance)
    const parsedHtml = useMemo(() => {
        if (isStreamingJson || isPlaceholderLoading || isBriefing || isAnalysis || isLab || isInteraction) return null;
        const html = parse(content, { breaks: true, gfm: true }) as string;
        return DOMPurify.sanitize(html);
    }, [content, isStreamingJson, isPlaceholderLoading, isBriefing, isAnalysis, isLab, isInteraction]);

    // --- RENDERERS ---

    if (isBriefing) return <BriefingReport content={content} />;
    if (isAnalysis) return <ImageAnalysisReport content={content} />;
    if (isLab) return <LabReport content={content} />;
    if (isInteraction) return <InteractionMatrix content={content} />;

    if (isPlaceholderLoading) {
        return <ReasoningIndicator mode={ChatMode.Auto} />;
    }

    if (isStreamingJson) {
        return (
            <div className="flex flex-col gap-2 p-2 w-full min-w-[300px] animate-pulse">
                <div className="flex items-center gap-2 text-blue-500">
                    <span className="animate-spin">⟳</span>
                    <span className="font-mono text-xs uppercase tracking-widest">Synthesizing Structured Data...</span>
                </div>
                <div className="space-y-2 opacity-50">
                    <div className="h-2 bg-slate-200 dark:bg-slate-700 w-3/4 rounded-sm"></div>
                    <div className="h-2 bg-slate-200 dark:bg-slate-700 w-1/2 rounded-sm"></div>
                    <div className="h-2 bg-slate-200 dark:bg-slate-700 w-full rounded-sm"></div>
                </div>
            </div>
        );
    }

    const typographyClasses = `
        prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed font-sans
        prose-headings:font-display prose-headings:font-bold prose-headings:tracking-tight prose-headings:text-slate-900 dark:prose-headings:text-white
        prose-p:my-2 prose-ul:my-2 prose-li:my-0.5
        prose-strong:font-semibold prose-strong:text-slate-900 dark:prose-strong:text-white
        prose-blockquote:bg-red-50 dark:prose-blockquote:bg-red-900/10 
        prose-blockquote:border-l-4 prose-blockquote:border-red-500 
        prose-blockquote:text-red-800 dark:prose-blockquote:text-red-200 
        prose-blockquote:py-3 prose-blockquote:px-4 prose-blockquote:rounded-r-sm
        prose-blockquote:not-italic prose-blockquote:font-medium
        prose-code:font-mono prose-code:text-[11px] prose-code:bg-slate-100 dark:prose-code:bg-slate-800 prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded-sm prose-code:text-slate-800 dark:prose-code:text-slate-200
        ${isLoading && isLast ? 'animate-soft-stream' : ''}
    `;

    return (
        <div 
            className={typographyClasses} 
            dangerouslySetInnerHTML={{ __html: parsedHtml || '' }}
        ></div>
    );
};

export default MessageContent;

import React, { useState } from 'react';
import type { ChatMessage } from '../types';
import { LinkIcon, DocumentTextIcon, ClipboardIcon, CheckIcon, AlertTriangleIcon, ShieldCheckIcon } from './icons';
import MessageContent from './MessageContent';

// Helper to detect high-credibility domains for medical info
const isHighCredibilitySource = (uri: string) => {
    try {
        const url = new URL(uri);
        const domain = url.hostname.toLowerCase();
        return domain.endsWith('.gov') || 
               domain.endsWith('.org') || 
               domain.endsWith('.edu') || 
               domain.includes('mayoclinic') ||
               domain.includes('webmd') || 
               domain.includes('medscape') ||
               domain.includes('ncbi') ||
               domain.includes('pubmed');
    } catch {
        return false;
    }
};

const MapPinIcon: React.FC<{className?: string}> = (props) => (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" {...props}>
        <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
    </svg>
);

interface MessageProps {
    message: ChatMessage;
    isLoading?: boolean;
    isLast?: boolean;
    onImageLoad?: () => void;
    onViewImage?: (src: string, alt: string) => void;
}

const Message: React.FC<MessageProps> = ({ message, isLoading, isLast, onImageLoad, onViewImage }) => {
    const isModel = message.role === 'model';
    const [isCopied, setIsCopied] = useState(false);

    // Safety Alert Detection (Keep simple string check at container level for styling)
    const isCriticalAlert = isModel && message.content.includes("🛑 CRITICAL SAFETY WARNING");

    // Determine content to pass to renderer
    const contentToRender = (message.role === 'user' && message.displayContent) 
        ? message.displayContent 
        : message.content;

    const handleCopy = () => {
        navigator.clipboard.writeText(message.content);
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
    };

    return (
        <div className={`flex flex-col gap-1 group animate-slide-up ${isModel ? 'items-start' : 'items-end'}`}>

            {/* Technical Header Label / Timestamp */}
            <div className="flex items-center gap-2 px-1 opacity-60 select-none">
                <div className={`h-1.5 w-1.5 rounded-none ${isModel ? (isCriticalAlert ? 'bg-red-500 animate-pulse' : 'bg-blue-500') : 'bg-slate-400'}`}></div>
                <span className={`text-[9px] font-mono uppercase tracking-widest ${isModel ? (isCriticalAlert ? 'text-red-500 font-bold' : 'text-blue-600 dark:text-blue-400') : 'text-slate-500'}`}>
                    {isModel ? (isCriticalAlert ? 'CRITICAL_SAFETY_INTERVENTION' : 'CIL_OUTPUT') : 'USER_INPUT_LOG'}
                </span>
                {isModel && (
                     <span className="text-[9px] font-mono text-slate-400 border-l border-slate-300 dark:border-slate-700 pl-2">
                        {new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                    </span>
                )}
            </div>

            {/* Main Data Block */}
            <div className={`
                relative max-w-full md:max-w-3xl p-5 border shadow-sm transition-all duration-300
                ${isModel 
                    ? isCriticalAlert 
                        ? 'bg-red-50 dark:bg-red-950/30 border-red-500 shadow-red-500/10 border-l-[4px]'
                        : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-800 border-l-[4px] border-l-blue-500 text-left' 
                    : 'bg-slate-50 dark:bg-slate-800/40 border-slate-200 dark:border-slate-700 border-l-[4px] border-l-slate-400 text-left'
                }
            `}>

                {/* Critical Alert Badge Overlay */}
                {isCriticalAlert && (
                    <div className="absolute -top-3 left-4 bg-red-600 text-white px-3 py-0.5 text-[10px] font-bold uppercase tracking-widest rounded-sm shadow-md flex items-center gap-2 z-10">
                        <AlertTriangleIcon className="w-3 h-3" />
                        <span>Protocol Violation Detected</span>
                    </div>
                )}

                {/* Copy Button */}
                {isModel && !isLoading && (
                    <button 
                        onClick={handleCopy}
                        className="absolute top-2 right-2 p-1.5 rounded-sm text-slate-400 hover:text-blue-600 hover:bg-slate-100 dark:hover:bg-slate-800 opacity-0 group-hover:opacity-100 transition-all z-20"
                        title="Copy to Clipboard"
                    >
                        {isCopied ? <CheckIcon className="w-3.5 h-3.5 text-green-500" /> : <ClipboardIcon className="w-3.5 h-3.5" />}
                    </button>
                )}

                {/* File Attachment Visualization */}
                {message.filePreview && (
                    <div className="mb-4 pb-4 border-b border-slate-100 dark:border-slate-800/50">
                         {message.filePreview.type.startsWith('image/') && message.filePreview.url ? (
                             <div className="relative inline-block group/img">
                                <button 
                                    onClick={() => onViewImage?.(message.filePreview!.url!, message.filePreview!.name)}
                                    className="block overflow-hidden border border-slate-200 dark:border-slate-700 bg-slate-100 dark:bg-black"
                                >
                                    <img 
                                        src={message.filePreview.url} 
                                        alt={message.filePreview.name} 
                                        onLoad={onImageLoad}
                                        className="max-w-[200px] max-h-[200px] object-contain block grayscale-[20%] group-hover/img:grayscale-0 transition-all duration-500" 
                                    />
                                </button>
                                <div className="mt-1 flex items-center justify-between text-[10px] font-mono text-slate-400 max-w-[200px]">
                                    <span className="truncate">IMG: {message.filePreview.name}</span>
                                    <span className="text-blue-500 opacity-0 group-hover/img:opacity-100 transition-opacity cursor-pointer">[EXPAND]</span>
                                </div>
                            </div>
                        ) : (
                             <div className="flex items-center gap-3 p-2 bg-slate-100 dark:bg-slate-800 border-l-2 border-slate-400 w-fit pr-4">
                                <DocumentTextIcon className="w-5 h-5 text-slate-500" />
                                <div>
                                    <p className="font-mono text-xs font-bold text-slate-700 dark:text-slate-300">{message.filePreview.name}</p>
                                    <p className="text-[10px] text-slate-400 uppercase tracking-wide">DATA_INGESTED</p>
                                 </div>
                            </div>
                        )}
                    </div>
                )}

                {/* Content Rendering Delegated to MessageContent */}
                <MessageContent 
                    content={contentToRender} 
                    role={message.role} 
                    isLoading={!!isLoading} 
                    isLast={!!isLast} 
                />

                {/* Grounding Sources Footer */}
                {message.sources && message.sources.length > 0 && (
                    <div className="mt-6 pt-3 border-t border-dashed border-slate-200 dark:border-slate-800">
                        <div className="flex items-center gap-2 mb-2">
                            <ShieldCheckIcon className="w-3 h-3 text-slate-400" />
                            <span className="text-[10px] font-mono font-bold text-slate-400 uppercase tracking-widest">Verified Sources</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {message.sources.map((source, i) => {
                                if (source.web) {
                                    const isTrusted = isHighCredibilitySource(source.web.uri);
                                    return (
                                        <a key={i} href={source.web.uri} target="_blank" rel="noopener noreferrer"
                                            className={`flex items-center gap-1.5 px-2 py-1 text-[10px] font-medium border transition-colors rounded-sm max-w-full
                                                ${isTrusted 
                                                    ? 'bg-green-50 dark:bg-green-900/10 border-green-200 dark:border-green-900 text-green-700 dark:text-green-400 hover:bg-green-100 dark:hover:bg-green-900/30' 
                                                    : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700'
                                                }`}
                                        >
                                            {isTrusted ? <ShieldCheckIcon className="w-3 h-3 text-green-500" /> : <LinkIcon className="w-3 h-3 text-blue-400" />}
                                            <span className="truncate max-w-[200px]">{source.web.title}</span>
                                        </a>
                                    );
                                }
                                if (source.maps) {
                                    return (
                                        <a key={i} href={source.maps.uri} target="_blank" rel="noopener noreferrer"
                                            className="flex items-center gap-1.5 bg-slate-50 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/20 border border-slate-200 dark:border-slate-700 px-2 py-1 text-[10px] font-medium text-slate-600 dark:text-slate-300 transition-colors"
                                        >
                                            <MapPinIcon className="w-3 h-3 text-blue-500" />
                                            <span className="truncate max-w-[200px]">{source.maps.title}</span>
                                        </a>
                                    );
                                }
                                return null;
                            })}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Message;

import React, { useState, useRef, useCallback, KeyboardEvent, useLayoutEffect, useEffect } from 'react';
import type { UploadedFile, ChatMode } from '../types';
import { ChatMode as ChatModeEnum } from '../types';
import { PaperclipIcon, SendIcon, XCircleIcon, BriefingIcon, UserIcon, DrugsIcon, DownloadIcon, DocumentTextIcon, MicrophoneIcon, CameraIcon, LiveIcon, StopIcon } from './icons';
import { useSpeechRecognition } from '../hooks/useSpeechRecognition';

interface InputBarProps {
    onSend: (prompt: string) => void;
    onClearFile: () => void;
    setUploadedFile: (file: UploadedFile) => void;
    isLoading: boolean;
    currentMode: ChatMode;
    uploadedFile: UploadedFile | null;
    toggleLiveSession: () => void;
    isLiveSessionActive: boolean;
    onStop?: () => void;
}

const QUICK_COMMANDS = [
  { command: '/brief', description: 'Shift briefing', icon: BriefingIcon },
  { command: '/patient ', description: 'Patient summary', icon: UserIcon },
  { command: '/drugs ', description: 'Check drugs', icon: DrugsIcon },
  { command: '/export', description: 'Export PDF', icon: DownloadIcon },
];

const InputBar: React.FC<InputBarProps> = ({ onSend, onClearFile, setUploadedFile, isLoading, currentMode, uploadedFile, toggleLiveSession, isLiveSessionActive, onStop }) => {
    const [prompt, setPrompt] = useState('');
    const [showCommands, setShowCommands] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const cameraInputRef = useRef<HTMLInputElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    const { isListening, toggleListening, stopListening } = useSpeechRecognition({
        onResult: (transcript) => setPrompt(transcript),
        onError: (err) => alert(err)
    });

    useEffect(() => {
        let activeUrl = uploadedFile?.url;
        return () => {
            if (activeUrl) setTimeout(() => URL.revokeObjectURL(activeUrl!), 1000);
        };
    }, [uploadedFile]);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            if (file.size > 4 * 1024 * 1024) {
                alert("File is too large. Please select a file smaller than 4MB.");
                return;
            }
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                const uploadPayload: UploadedFile = { file, base64, type: file.type };
                if (file.type.startsWith('image/')) {
                    uploadPayload.url = URL.createObjectURL(file);
                }
                setUploadedFile(uploadPayload);
            };
            reader.readAsDataURL(file);
        }
        if (event.target) event.target.value = '';
    };

    const handleSendClick = useCallback(() => {
        const canSend = !isLoading || isLiveSessionActive;
        if (canSend) {
            if (isListening) stopListening();
            onSend(prompt);
            setPrompt('');
            setShowCommands(false);
        }
    }, [isLoading, isLiveSessionActive, onSend, prompt, isListening, stopListening]);

    const handleCommandSelect = (command: string) => {
        setPrompt(command);
        setShowCommands(false);
        setTimeout(() => textareaRef.current?.focus(), 0);
    };

    const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
        if (event.key === 'Enter' && !event.shiftKey) {
            event.preventDefault();
            handleSendClick();
        }
    };

    const resizeTextarea = () => {
        const textarea = textareaRef.current;
        if (textarea) {
            textarea.style.height = 'auto';
            if (prompt === '') {
                textarea.style.height = '';
                return;
            }
            const scrollHeight = textarea.scrollHeight;
            textarea.style.height = `${Math.min(scrollHeight, 150)}px`;
        }
    };

    const handleTextareaInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const value = e.target.value;
        setPrompt(value);
        setShowCommands(value.trim() === '/' || value.endsWith(' /'));
    };

    useLayoutEffect(() => { resizeTextarea(); }, [prompt]);
    const handleBlur = () => { setTimeout(() => setShowCommands(false), 200); };

    const isInputDisabled = (isLoading && !isLiveSessionActive) || isListening;
    const placeholderText = isLiveSessionActive 
        ? 'Voice Stream Active - Listening...' 
        : (isListening ? 'Dictation Active...' : 'Enter clinical instruction (/ for commands)...');

    const showStopButton = isLoading && !isLiveSessionActive && onStop;

    return (
        <footer className="flex-shrink-0 p-4 pb-6 z-30 pointer-events-none">
            <div className="max-w-4xl mx-auto pointer-events-auto">
                <div className={`relative transition-all duration-300 transform ${isLiveSessionActive ? 'scale-[1.02]' : ''}`}>

                    {/* Attachment Pill */}
                     {uploadedFile && (
                        <div className="absolute bottom-full left-0 mb-3 animate-slide-up z-20">
                             <div className="flex items-center gap-3 bg-slate-900 text-white p-2 pr-4 rounded-sm shadow-xl border-l-4 border-blue-500">
                                {uploadedFile.url && uploadedFile.type.startsWith('image/') ? (
                                     <img src={uploadedFile.url} alt="Attachment" className="w-8 h-8 object-cover rounded-sm" />
                                ) : (
                                    <div className="w-8 h-8 flex items-center justify-center bg-slate-800 rounded-sm">
                                        <DocumentTextIcon className="w-4 h-4 text-slate-400" />
                                    </div>
                                )}
                                <div className="flex flex-col">
                                    <span className="text-xs font-mono font-bold max-w-[150px] truncate">{uploadedFile.file.name}</span>
                                    <span className="text-[10px] text-slate-400 uppercase tracking-wider">Ready to Ingest</span>
                                </div>
                                <button onClick={onClearFile} className="ml-2 text-slate-400 hover:text-red-400">
                                    <XCircleIcon className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    )}

                    {/* Quick Command Menu */}
                     {showCommands && (
                        <div className="absolute bottom-full left-0 mb-2 bg-white dark:bg-slate-900 rounded-sm shadow-2xl border border-slate-300 dark:border-slate-700 w-64 animate-slide-up z-20 overflow-hidden">
                            <div className="bg-slate-100 dark:bg-slate-800 px-3 py-1.5 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center">
                                 <p className="text-[10px] font-mono font-bold uppercase tracking-wider text-slate-500">Quick Execute</p>
                            </div>
                            <ul className="p-0">
                                {QUICK_COMMANDS.map(({ command, description, icon: Icon }) => (
                                    <li key={command} className="border-b border-slate-100 dark:border-slate-800 last:border-0">
                                        <button
                                            onClick={() => handleCommandSelect(command)}
                                            className="w-full text-left flex items-center gap-3 p-3 hover:bg-blue-50 dark:hover:bg-slate-800/50 transition-colors group"
                                        >
                                            <div className="text-slate-400 group-hover:text-blue-500">
                                                <Icon className="w-4 h-4" />
                                            </div>
                                            <div>
                                                <p className="font-mono text-xs font-bold text-slate-700 dark:text-slate-200 group-hover:text-blue-600 dark:group-hover:text-blue-400">{command}</p>
                                                <p className="text-[10px] text-slate-400">{description}</p>
                                            </div>
                                        </button>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {/* Main Console Container */}
                    <div className={`
                        flex items-end gap-0 rounded-sm shadow-2xl transition-all duration-300 border-2 overflow-hidden
                        ${isLiveSessionActive 
                            ? 'bg-slate-900 border-red-500 shadow-red-900/30' 
                            : 'bg-white dark:bg-slate-900 border-slate-300 dark:border-slate-600 focus-within:border-blue-500 focus-within:shadow-blue-500/20'
                        }
                    `}>
                        {/* Live Mode Toggle */}
                        <button
                            onClick={toggleLiveSession}
                            className={`flex-shrink-0 self-stretch w-14 flex flex-col items-center justify-center transition-all border-r ${
                                isLiveSessionActive 
                                ? 'bg-red-600 text-white border-red-500' 
                                : 'bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-slate-200 dark:border-slate-700 hover:text-red-500 hover:bg-red-50 dark:hover:bg-slate-700'
                            }`}
                            title={isLiveSessionActive ? "Stop Live Session" : "Start Live Consult"}
                        >
                            <LiveIcon className={`w-5 h-5 md:w-6 md:h-6 ${isLiveSessionActive ? 'animate-pulse' : ''}`} />
                            <span className="text-[9px] font-mono font-bold mt-1 uppercase">
                                {isLiveSessionActive ? 'LIVE' : 'VOICE'}
                            </span>
                        </button>

                        {/* Text Input Area */}
                        <div className="flex-1 flex flex-col relative min-w-0">
                            {/* Live Active Overlay */}
                            {isLiveSessionActive && (
                                <div className="absolute inset-0 z-10 bg-slate-900/90 flex items-center px-4 gap-3 animate-fade-in pointer-events-none">
                                    <div className="flex gap-1 h-3">
                                        {[1,2,3,4].map(i => <div key={i} className="w-1 bg-red-500 animate-music" style={{animationDuration: `${Math.random() * 0.5 + 0.2}s`}}></div>)}
                                    </div>
                                    <span className="font-mono text-xs text-red-400 uppercase tracking-widest animate-pulse">
                                        Open Mic Active // Listening...
                                    </span>
                                </div>
                            )}

                            <textarea
                                ref={textareaRef}
                                value={prompt}
                                onChange={handleTextareaInput}
                                onKeyDown={handleKeyDown}
                                onBlur={handleBlur}
                                placeholder={placeholderText}
                                rows={1}
                                className={`w-full bg-transparent resize-none outline-none py-4 px-4 text-sm font-medium leading-relaxed max-h-32 font-mono ${
                                    isLiveSessionActive ? 'text-transparent' : 'text-slate-900 dark:text-white placeholder-slate-400'
                                }`}
                                disabled={isInputDisabled}
                            />
                        </div>

                        {/* Tool Actions */}
                        <div className="flex items-center gap-1 self-end pb-2 pr-2">
                            <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*,application/pdf,.txt,.md" className="hidden" />
                            <input type="file" ref={cameraInputRef} onChange={handleFileChange} accept="image/*" capture="environment" className="hidden" />

                            {!isLiveSessionActive && (
                                <>
                                    <button onClick={() => fileInputRef.current?.click()} className="p-2 text-slate-400 hover:text-blue-500 transition-colors rounded-sm hover:bg-slate-100 dark:hover:bg-slate-800" title="Attach File">
                                        <PaperclipIcon className="w-5 h-5" />
                                    </button>
                                    <button onClick={() => cameraInputRef.current?.click()} className="p-2 text-slate-400 hover:text-blue-500 transition-colors rounded-sm hover:bg-slate-100 dark:hover:bg-slate-800" title="Camera Capture">
                                        <CameraIcon className="w-5 h-5" />
                                    </button>
                                    {currentMode !== ChatModeEnum.Live && (
                                        <button 
                                            onClick={() => toggleListening(prompt)} 
                                            className={`p-2 transition-colors rounded-sm hover:bg-slate-100 dark:hover:bg-slate-800 ${isListening ? 'text-red-500 bg-red-50 dark:bg-red-900/20 animate-pulse border border-red-200 dark:border-red-900' : 'text-slate-400 hover:text-blue-500'}`}
                                            title="Dictate Text"
                                        >
                                            <MicrophoneIcon className="w-5 h-5" />
                                        </button>
                                    )}
                                </>
                            )}

                             {/* Execute Button */}
                            {(!isLiveSessionActive && currentMode !== ChatModeEnum.Live) && (
                                <button 
                                    onClick={showStopButton ? onStop : handleSendClick}
                                    disabled={!showStopButton && (isInputDisabled || (!prompt.trim() && !uploadedFile))}
                                    className={`ml-2 flex-shrink-0 h-10 w-10 rounded-sm flex items-center justify-center transition-all shadow-sm ${
                                        showStopButton
                                        ? 'bg-slate-700 text-white hover:bg-slate-600'
                                        : 'bg-blue-600 hover:bg-blue-500 text-white disabled:opacity-50 disabled:bg-slate-200 dark:disabled:bg-slate-800 dark:disabled:text-slate-600'
                                    }`}
                                >
                                    {showStopButton ? <StopIcon className="w-4 h-4" /> : <SendIcon className="w-4 h-4" />}
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </footer>
    );
};

